// GitHub 실행 목록에서 아직 알리지 않은 실패만 골라 Discord 페이로드까지 만든다.
//
// 중복 방지: 마지막으로 본 run id 를 워크플로우 static data 에 보관한다.
// n8n 이 실행 간에 유지해주므로 Data Store 를 따로 붙이지 않아도 된다.
const store = $getWorkflowStaticData('global');
const runs = $input.first().json.workflow_runs || [];
const lastSeen = Number(store.lastSeenRunId || 0);

// 첫 실행이면 과거 실패 전체를 쏟아내지 않는다 — 기준선만 세우고 조용히 끝낸다.
if (!lastSeen) {
  store.lastSeenRunId = runs.length ? Math.max(...runs.map((r) => r.id)) : 0;
  return [];
}

// run id 는 단조 증가하므로 "이보다 큰가"로 새 실패를 가릴 수 있다.
const fresh = runs.filter((r) => r.id > lastSeen);
if (fresh.length === 0) return [];
store.lastSeenRunId = Math.max(...fresh.map((r) => r.id));
fresh.sort((a, b) => a.id - b.id); // 오래된 것부터 읽히도록

// Discord 임베드도 여기서 조립한다. HTTP 노드의 한 줄 표현식으로 두면 읽을 수도,
// prettier 로 포맷할 수도, 테스트할 수도 없다 — 실제로 551자 한 줄이었다.
const firstLine = (msg) => (msg || '').split('\n')[0].slice(0, 120);

return fresh.map((r) => ({
  json: {
    embeds: [
      {
        title: `🔴 ${r.name} 실패`,
        url: r.html_url,
        description: `\`${(r.head_sha || '').slice(0, 7)}\` ${firstLine(r.head_commit && r.head_commit.message)}`,
        color: 15158332,
        fields: [
          { name: '브랜치', value: r.head_branch || '?', inline: true },
          { name: '트리거', value: r.event || '?', inline: true },
          { name: '실행자', value: (r.actor && r.actor.login) || '?', inline: true },
        ],
        footer: { text: `jump-section • run #${r.run_number}` },
        timestamp: r.created_at,
      },
    ],
  },
}));
